/// Frozen legacy shape. Never rename a field without checking the client.
#[derive(Serialize, Deserialize)]
struct LegacyQuote {
    #[serde(rename = "SKU")]        sku: String,
    #[serde(rename = "unit_price")] unit_price: String,          // decimal as text
    #[serde(default = "eur", rename = "ccy")] ccy: String,
}
impl TryFrom<LegacyQuote> for Quote {            // canonical model
    type Error = LegacyMappingError;
    fn try_from(l: LegacyQuote) -> Result<Self, Self::Error> {
        Ok(Quote { sku: l.sku, cents: parse_decimal(&l.unit_price)?, currency: l.ccy })
    }
}
